usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Conversations.Items.Get(
		context.TODO(),
		"conv_123",
		"msg_abc",
		openai.ConversationItemGetParams{
			Include: []openai.IncludeEnum{openai.IncludeEnumFileSearchCallResults},
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
